  'منتج غير ظاهر في القائمة': { en: 'Product not in the list', fr: 'Produit absent de la liste', tr: 'Listede olmayan ürün', zh: '不在列表中的产品' },
  // ——— خريطة Google الموحّدة داخل التطبيق (بلا مفتاح بحث) ———
  'خريطة Google واحدة داخل التطبيق لكل من فُعّلت له الميزة. حتى يُضبط مفتاح Google الموحّد للمنصّة: يرى المندوب المحلات حوله على الخريطة ويضيف المحل بزر «أنا عند المحل الآن» أو برابطه، فيحسب له التوقّع ويوجّهه العقل — والبحث التلقائي عن كل المحلات المجاورة يعمل فور ضبط المفتاح': { en: "One Google map inside the app for everyone with the feature. Until the platform’s shared Google key is set, the rep sees nearby shops on the map and adds a shop with “I’m at the shop now” or its link, then gets the estimate and the brain’s guidance — automatic search of all nearby shops starts as soon as the key is set", fr: "Une seule carte Google dans l’application pour tous ceux qui ont la fonctionnalité. En attendant la clé Google commune de la plateforme, le commercial voit les commerces proches sur la carte et ajoute un commerce via « Je suis au magasin » ou son lien, puis reçoit l’estimation et les conseils du cerveau — la recherche automatique démarre dès que la clé est configurée", tr: "Özelliği açık herkes için uygulama içinde tek bir Google haritası. Platformun ortak Google anahtarı ayarlanana kadar temsilci yakındaki dükkânları haritada görür, dükkânı “Şu an dükkândayım” veya bağlantısıyla ekler, tahmini ve beynin yönlendirmesini alır — tüm yakın dükkânların otomatik araması anahtar ayarlanınca başlar", zh: "应用内为所有开通该功能的用户提供同一张 Google 地图。在平台统一的 Google 密钥配置之前，业务员可在地图上查看附近门店，通过“我现在在店里”或链接添加门店，获得预测和大脑指导——配置密钥后即自动搜索附近所有门店" },
  'خريطة Google': { en: "Google map", fr: "Carte Google", tr: "Google haritası", zh: "Google 地图" },
  'اعرض المحلات حولي على خريطة Google': { en: "Show shops around me on Google Maps", fr: "Afficher les commerces autour de moi sur Google Maps", tr: "Çevremdeki dükkânları Google Haritalar’da göster", zh: "在 Google 地图上显示我周围的门店" },
  'أضف محلاً ليحسب له العقل التوقّع': { en: "Add a shop for the brain to estimate", fr: "Ajoutez un commerce pour que le cerveau l’estime", tr: "Beynin tahmin etmesi için bir dükkân ekleyin", zh: "添加门店，由大脑进行预测" },
  'عند باب المحل اضغط «أنا عند المحل الآن»، أو الصق رابط المحل من خرائط Google': { en: "At the shop door tap “I’m at the shop now”, or paste the shop’s Google Maps link", fr: "À la porte du commerce, touchez « Je suis au magasin » ou collez le lien Google Maps du commerce", tr: "Dükkân kapısında “Şu an dükkândayım”a dokunun veya dükkânın Google Haritalar bağlantısını yapıştırın", zh: "在门店门口点击“我现在在店里”，或粘贴门店的 Google 地图链接" },
  'الصق رابط المحل من خرائط Google': { en: "Paste the shop link from Google Maps", fr: "Collez le lien du commerce depuis Google Maps", tr: "Dükkânın Google Haritalar bağlantısını yapıştırın", zh: "粘贴 Google 地图中的门店链接" },
  'الصق': { en: "Paste", fr: "Coller", tr: "Yapıştır", zh: "粘贴" },
  'اسم المحل (اختياري)': { en: "Shop name (optional)", fr: "Nom du commerce (facultatif)", tr: "Dükkân adı (isteğe bağlı)", zh: "门店名称（可选）" },
  'أضف وتوقّع': { en: "Add & estimate", fr: "Ajouter et estimer", tr: "Ekle ve tahmin et", zh: "添加并预测" },
  'أنا عند المحل الآن': { en: "I’m at the shop now", fr: "Je suis au magasin", tr: "Şu an dükkândayım", zh: "我现在在店里" },
  'تعذّرت إضافة المحل': { en: "Could not add the shop", fr: "Impossible d’ajouter le commerce", tr: "Dükkân eklenemedi", zh: "无法添加门店" },
  'اطلب توجيه المستشار للمحلات المضافة': { en: "Ask the advisor to guide me on the added shops", fr: "Demander au conseiller un plan pour les commerces ajoutés", tr: "Eklenen dükkânlar için danışmandan yönlendirme iste", zh: "请顾问为已添加的门店提供指导" },
